-- PERFORM — SCHEMA_v71_workout_template_catalog.sql
-- ============================================================================
-- Catalogo iniziale di split allenamento professionali (SCHEMA_v59 già crea
-- la tabella workout_templates e la UI coach per salvare/applicare/eliminare
-- template — qui si aggiunge SOLO il contenuto: 8 split reali,
-- pensate per rispettare i principi consolidati di ipertrofia/forza (volume
-- settimanale per gruppo muscolare nel range raccomandato, frequenza 1-3x a
-- seconda dello split, recupero tra sedute pesanti sullo stesso distretto,
-- selezione esercizi composti + isolamento) — dal principiante (Full Body 3
-- giorni) all'atleta avanzato (PPL/Upper-Lower ad alta frequenza, Bro Split,
-- Arnold Split). "days" ha la stessa forma già usata da saveWeekWorkout: 7
-- elementi Lun→Dom, null = riposo.
--
-- Estende anche exercise_library con gli esercizi nuovi usati qui (già
-- classificati con muscolo diretto/sinergici) — così compaiono subito nel
-- menu a tendina raggruppato per muscolo del coach e nei suggerimenti di
-- ricerca dei clienti Premium, non solo dentro questi template.
--
-- Da eseguire in Supabase SQL Editor DOPO SCHEMA_v59 (se non già fatto) e
-- SCHEMA_v39 (exercise_library, quasi certamente già presente). Idempotente:
-- riesguibile senza duplicare — i nomi dei template sono marcati con un
-- prefisso riconoscibile e vengono ripuliti prima di reinserirli.

-- Nuovi esercizi usati nei template qui sotto, in libreria condivisa —
-- "on conflict do nothing": se un esercizio con lo stesso nome esiste già
-- (es. il coach l'aveva già classificato a mano), non lo tocca.
insert into public.exercise_library (name, direct, indirect, created_by) values
  ('Panca inclinata manubri', ARRAY['Petto']::text[], ARRAY['Deltoide Ant', 'Tricipiti']::text[], null),
  ('Military press bilanciere', ARRAY['Deltoide Ant']::text[], ARRAY['Deltoide Lat', 'Tricipiti']::text[], null),
  ('Alzate laterali manubri', ARRAY['Deltoide Lat']::text[], ARRAY[]::text[], null),
  ('Push down ai cavi', ARRAY['Tricipiti']::text[], ARRAY[]::text[], null),
  ('Leg press 45°', ARRAY['Quadricipiti']::text[], ARRAY['Glutei']::text[], null),
  ('Chest press machine', ARRAY['Petto']::text[], ARRAY['Tricipiti', 'Deltoide Ant']::text[], null),
  ('Dip alle parallele (petto)', ARRAY['Petto']::text[], ARRAY['Tricipiti', 'Deltoide Ant']::text[], null),
  ('Arnold press', ARRAY['Deltoide Ant']::text[], ARRAY['Deltoide Lat', 'Tricipiti']::text[], null),
  ('Alzate laterali ai cavi', ARRAY['Deltoide Lat']::text[], ARRAY[]::text[], null),
  ('Skull crusher', ARRAY['Tricipiti']::text[], ARRAY[]::text[], null),
  ('Trazioni alla sbarra', ARRAY['Dorsali']::text[], ARRAY['Bicipiti', 'Deltoide Post']::text[], null),
  ('Pulley basso', ARRAY['Dorsali']::text[], ARRAY['Bicipiti', 'Trapezio']::text[], null),
  ('Rematore manubrio monolaterale', ARRAY['Dorsali']::text[], ARRAY['Bicipiti', 'Deltoide Post']::text[], null),
  ('Alzate posteriori manubri', ARRAY['Deltoide Post']::text[], ARRAY['Trapezio']::text[], null),
  ('Curl a martello', ARRAY['Bicipiti']::text[], ARRAY[]::text[], null),
  ('Front squat', ARRAY['Quadricipiti']::text[], ARRAY['Glutei']::text[], null),
  ('Affondi manubri', ARRAY['Quadricipiti']::text[], ARRAY['Glutei', 'Femorali']::text[], null),
  ('Calf raise seduto', ARRAY['Polpacci']::text[], ARRAY[]::text[], null),
  ('Preacher curl', ARRAY['Bicipiti']::text[], ARRAY[]::text[], null),
  ('Good morning', ARRAY['Femorali']::text[], ARRAY['Glutei', 'Lombari']::text[], null),
  ('Affondi bulgari', ARRAY['Glutei']::text[], ARRAY['Quadricipiti', 'Femorali']::text[], null),
  ('Pull-over ai cavi', ARRAY['Dorsali']::text[], ARRAY['Tricipiti']::text[], null),
  ('Shrug bilanciere', ARRAY['Trapezio']::text[], ARRAY[]::text[], null)
on conflict (name) do nothing;

-- Template di split: ripulisce eventuali righe già inserite da una
-- esecuzione precedente di QUESTA stessa migrazione (stesso nome, coach
-- di sistema), poi le reinserisce — così è idempotente senza duplicare.
delete from public.workout_templates
where coach_id = (select id from auth.users where email = 'danielmarsini@coach.com')
  and name in ('Push / Pull / Legs — 6 giorni (alta frequenza)', 'Push / Pull / Legs — 3 giorni (principianti)', 'Upper / Lower — 4 giorni (intermedio)', 'Upper / Lower — 6 giorni (riposo solo la domenica)', 'Full Body — 3 giorni (principianti/intermedio)', 'Full Body — 4 giorni (intermedio)', 'Bro Split — 5 giorni (un gruppo al giorno)', 'Arnold Split — 6 giorni (Petto-Dorso / Spalle-Braccia / Gambe)');

