-- Il catalogo deve essere sfogliabile anche dagli utenti Premium (non solo
-- dal coach): estende la policy SELECT di SCHEMA_v59 (prima solo
-- is_coach()) a chiunque abbia effettuato l'accesso — la scrittura
-- (insert/delete) resta SOLO al coach, invariata.
drop policy if exists "workout_templates_select" on public.workout_templates;
create policy "workout_templates_select" on public.workout_templates for select
  to authenticated using ( true );
